// Calculate total mass and center of mass velocity
std::vector<double> total_mass(3, 0.0);
double mass_sum = 0.0;
for (std::size_t i = 0; i < masses.size(); ++i) {
    mass_sum += masses[i];
    for (int d = 0; d < 3; ++d) {
        total_mass[d] += masses[i] * velocities[i][d];
    }
}
vec3 com_velocity;
for (int d = 0; d < 3; ++d) {
    com_velocity[d] = total_mass[d] / mass_sum;
}

// Remove center of mass motion
for (std::size_t i = 0; i < velocities.size(); ++i) {
    for (int d = 0; d < 3; ++d) {
        velocities[i][d] -= com_velocity[d];
    }
}

// Initialize velocities from Maxwell-Boltzmann distribution
const double kB = 1.380649e-23; // Boltzmann constant (SI units)
const double v_scale = std::sqrt(3.0 * kB * temperature / mass_sum);

for (std::size_t i = 0; i < velocities.size(); ++i) {
    // Generate random direction (uniformly distributed on unit sphere)
    double theta = std::acos(2.0 * std::rand() / RAND_MAX - 1.0);
    double phi = 2.0 * M_PI * std::rand() / RAND_MAX;
    double sin_theta = std::sin(theta);
    velocities[i][0] = v_scale * sin_theta * std::cos(phi);
    velocities[i][1] = v_scale * sin_theta * std::sin(phi);
    velocities[i][2] = v_scale * std::cos(theta);

    // Scale velocity by sqrt(mass_i) to account for different masses
    double mass_sqrt = std::sqrt(masses[i]);
    for (int d = 0; d < 3; ++d) {
        velocities[i][d] *= mass_sqrt;
    }
}

// Re-remove center of mass motion (due to random initialization)
total_mass.assign(3, 0.0);
mass_sum = 0.0;
for (std::size_t i = 0; i < masses.size(); ++i) {
    mass_sum += masses[i];
    for (int d = 0; d < 3; ++d) {
        total_mass[d] += masses[i] * velocities[i][d];
    }
}
for (std::size_t i = 0; i < velocities.size(); ++i) {
    for (int d = 0; d < 3; ++d) {
        velocities[i][d] -= total_mass[d] / mass_sum;
    }
}
// END_CODE

